import random
import struct
from typing import List

# Generator for big-endian integer byte strings suitable for bytes_to_words()
# Goals:
# - Produce valid big-endian encodings of non-negative integers
# - Vary length from 0..128
# - Include interesting edge cases: zero-length, all-zero, leading zeros, exact 64-bit boundaries,
#   multi-word boundaries, maximal length, minimal non-zero, alternating patterns, random values.
# - Deterministic given a seed, yet diverse across calls.

_MAX_LEN = 128

def _be_from_int(n: int, min_len: int = 1) -> bytes:
    if n < 0:
        n = 0
    if n == 0:
        return b"\x00" * max(1, min_len)
    out = bytearray()
    while n:
        out.append(n & 0xFF)
        n >>= 8
    out = bytes(reversed(out))
    if len(out) < min_len:
        out = b"\x00" * (min_len - len(out)) + out
    return out

def _pad_left(data: bytes, total_len: int, pad_byte: int = 0) -> bytes:
    if total_len <= len(data):
        return data[:total_len]
    return bytes([pad_byte]) * (total_len - len(data)) + data

def _pattern_bytes(kind: str, length: int) -> bytes:
    if length <= 0:
        return b""
    if kind == "zero":
        return b"\x00" * length
    if kind == "ones":
        return b"\xFF" * length
    if kind == "inc":
        return bytes((i % 256 for i in range(length)))
    if kind == "dec":
        return bytes(((255 - i) % 256 for i in range(length)))
    if kind == "alt10":
        return (b"\x01\x00" * ((length + 1)//2))[:length]
    if kind == "altf0":
        return (b"\xFF\x00" * ((length + 1)//2))[:length]
    if kind == "msb_set":
        # Leading 0x80 then random tail
        tail = bytes(random.getrandbits(8) for _ in range(max(0, length-1)))
        return b"\x80" + tail
    # default random
    return bytes(random.getrandbits(8) for _ in range(length))

def _with_leading_zeros(core: bytes, lead_count: int) -> bytes:
    return b"\x00" * max(0, lead_count) + core

def _make_boundary_value(bits: int) -> bytes:
    # Create a value exactly at 2^bits - 1 (all ones) or 2^bits
    if bits <= 0:
        return b"\x00"
    if random.choice([True, False]):
        n = (1 << bits) - 1
    else:
        n = 1 << bits
    b = _be_from_int(n)
    return b

def _cap_len(b: bytes) -> bytes:
    # Ensure <= 128 bytes
    if len(b) <= _MAX_LEN:
        return b
    # Trim leading zeros preferentially; if none, truncate left (most significant) to fit
    lead_zeros = 0
    for ch in b:
        if ch == 0:
            lead_zeros += 1
        else:
            break
    if lead_zeros > 0:
        b = b[lead_zeros:]
    if len(b) > _MAX_LEN:
        b = b[-_MAX_LEN:]
    return b

def _choose_len() -> int:
    # Bias toward interesting lengths: 0, 1, 8, 9, 16, 24, 32, 63, 64, 65, 127, 128
    specials = [0,1,2,3,7,8,9,15,16,17,23,24,31,32,33,63,64,65,95,96,127,128]
    if random.random() < 0.6:
        return random.choice(specials)
    return random.randint(0, _MAX_LEN)

def _generate_case() -> bytes:
    choice = random.randint(0, 12)

    if choice == 0:
        # Zero-length
        return b""
    if choice == 1:
        # All zeros with random length
        L = _choose_len()
        return _pattern_bytes("zero", L)
    if choice == 2:
        # Minimal non-zero at varying positions with leading zeros
        L = max(1, _choose_len())
        pos = random.randint(0, max(0, L-1))
        b = bytearray(b"\x00" * L)
        b[pos] = 1
        return bytes(b)
    if choice == 3:
        # Exact 64-bit boundaries
        words = random.choice([1,2,3,4,7,8,9,0])
        if words == 0:
            return b""
        # Create a random little integer that spans that many 64b words (1..words bytes each non-zero)
        bits = 64*words - random.randint(0,63)
        val = random.getrandbits(max(1,bits))
        b = _be_from_int(val)
        # Optionally pad to align byte-length to 8*words exactly
        if random.random() < 0.5:
            target = 8*words
            b = _pad_left(b, target, 0)
        return _cap_len(b)
    if choice == 4:
        # Leading zeros then random core
        core_len = random.randint(1, max(1, _MAX_LEN//2))
        lead = random.randint(1, _MAX_LEN - core_len)
        core = _pattern_bytes("rand", core_len)
        return _with_leading_zeros(core, lead)
    if choice == 5:
        # Alternating patterns
        kind = random.choice(["alt10", "altf0", "inc", "dec"])
        L = _choose_len()
        return _pattern_bytes(kind, L)
    if choice == 6:
        # Boundary numeric values at 8,16,32,64,128,256,512 bits
        bits = random.choice([1,7,8,9,15,16,17,31,32,33,63,64,65,127,128,129,255,256,257])
        b = _make_boundary_value(bits)
        # Maybe add leading zeros to force trimming behavior
        if random.random() < 0.5:
            b = _with_leading_zeros(b, random.randint(1, 8))
        return _cap_len(b)
    if choice == 7:
        # Exactly fits N words (no leading zeros), random value using high bit set
        words = random.randint(1, 8)
        L = 8*words
        b = bytearray(_pattern_bytes("rand", L))
        if L > 0:
            b[0] |= 0x80
        return bytes(b)
    if choice == 8:
        # Right-aligned within target length with left zero padding (common output of words_to_bytes)
        target_len = _choose_len()
        core_len = random.randint(0, target_len)
        core = _pattern_bytes("rand", core_len)
        return _pad_left(core, target_len, 0)
    if choice == 9:
        # Single-byte values spanning all 0..255
        return bytes([random.randint(0,255)])
    if choice == 10:
        # Maximal length random with guaranteed non-zero MSB or zero-padded
        L = _MAX_LEN
        mode = random.choice(["msb_set", "zeros_left"])
        if mode == "msb_set":
            return _pattern_bytes("msb_set", L)
        core = _pattern_bytes("rand", random.randint(1, L))
        return _pad_left(core, L, 0)
    if choice == 11:
        # Numbers that will overflow small word counts (for ERR_MAX_DATA paths)
        # Create a length that likely requires > k words (k small)
        k = random.randint(1, 3)
        min_bytes = 8*(k+1)
        L = random.randint(min_bytes, min(_MAX_LEN, min_bytes + 16))
        b = _pattern_bytes("rand", L)
        # Ensure significant leading non-zero to avoid trimming to smaller size
        if L > 0 and b[0] == 0:
            b = bytes([random.randint(1,255)]) + b[1:]
        return b
    # choice == 12
    # Random length and bytes (default), maybe ensure non-zero value
    L = _choose_len()
    b = _pattern_bytes("rand", L)
    if L > 0 and random.random() < 0.3:
        # Ensure non-zero by setting one random byte
        idx = random.randrange(L)
        if b[idx] == 0:
            b = b[:idx] + bytes([1]) + b[idx+1:]
    return b


def generate(seed: int) -> bytes:
    random.seed(seed)
    # Compose possibly multiple segments to increase variety while staying <= 128
    segments: List[bytes] = []
    remaining = _MAX_LEN
    # Decide number of segments (including possibility of empty overall buffer)
    segs = random.choice([0, 1, 1, 1, 2, 2, 3])
    for _ in range(segs):
        seg = _generate_case()
        if len(seg) > remaining:
            seg = seg[:remaining]
        segments.append(seg)
        remaining -= len(seg)
        if remaining <= 0:
            break
    # For segs == 0, occasionally return empty to exercise len==0 path
    data = b"".join(segments)
    # Final cap to ensure <= 128 bytes
    if len(data) > _MAX_LEN:
        data = data[-_MAX_LEN:]
    return data
